mapper.select:
select t.* from ww_dimension t where 1=1

	and t.product = #{product}


	and t.dmsn_name = #{dmsnName}


	and instr(t.dmsn_name,#{lDmsnName}) > 0


and exists (
  select tsupr.product_id From ww_sys_user tsu,ww_product tp,ww_sys_user_product_ref tsupr 
    where tsu.login_name=tsupr.user_id and tp.p_id=tsupr.product_id 
      and tp.p_id=t.product and tsu.login_name=#{loginName}
) 

order by dmsn_name

mapper.update:
    UPDATE ww_dimension
    set 
	   dmsn_desc = #{description,jdbcType=VARCHAR}
	WHERE product = #{product} and dmsn_name = #{name}

mapper.delete:
    delete from ww_dimension where 1=1 
	
		and product = #{product}
	
	
		and dmsn_name = #{dmsnName}
